custom_css:
/* =============================================================================
   APPLE DESIGN SYSTEM  ·  for SillyTavern (iOS 18 / macOS Sonoma / visionOS)
   Pure Apple Human Interface language:
   - SF Pro typography system (strictly preserving Font Awesome icon fonts)
   - Multi-layer Gaussian frosted glass (Glassmorphism) + 1px specular hairline
   - Capsule buttons with hover luminescence & spring press (active: scale 0.96)
   - Floating frosted pill composer & clean chrome without industrial clutter
   - Seamless coordination with LittleWhiteBox (小白X), TavernHelper (酒馆助手),
     and Ny-Gemini interactive option cards.
   ============================================================================= */

:root {
    --ap-font: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display",
        "Helvetica Neue", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei UI",
        "Microsoft YaHei", "Noto Sans SC", "Segoe UI", sans-serif,
        "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji";
    --ap-mono: ui-monospace, "SF Mono", "SFMono-Regular", Menlo, Monaco, Consolas,
        "Noto Sans Mono", monospace;

    /* Apple Dark System Accent Colors */
    --ap-blue: #0a84ff;
    --ap-blue-hover: #409cff;
    --ap-blue-deep: #0066cc;
    --ap-cyan: #64d2ff;
    --ap-indigo: #5e5ce6;
    --ap-green: #30d158;
    --ap-orange: #ff9f0a;
    --ap-red: #ff453a;

    /* Translucent Fills & Hairlines */
    --ap-fill-1: rgba(128, 128, 140, 0.28);
    --ap-fill-2: rgba(120, 120, 132, 0.20);
    --ap-fill-3: rgba(120, 120, 132, 0.14);
    --ap-fill-4: rgba(120, 120, 132, 0.09);

    --ap-hairline: rgba(255, 255, 255, 0.14);
    --ap-hairline-strong: rgba(255, 255, 255, 0.24);
    --ap-hairline-subtle: rgba(255, 255, 255, 0.08);

    /* Labels */
    --ap-label: rgba(255, 255, 255, 0.95);
    --ap-label-2: rgba(235, 235, 245, 0.68);
    --ap-label-3: rgba(235, 235, 245, 0.40);

    /* Glass Materials */
    --ap-glass-pill: rgba(26, 26, 30, 0.62);
    --ap-glass-bubble: rgba(30, 30, 36, 0.60);
    --ap-glass-sheet: rgba(24, 24, 28, 0.82);
    --ap-glass-popover: rgba(34, 34, 40, 0.88);
    --ap-blur-sm: saturate(170%) blur(16px);
    --ap-blur-md: saturate(185%) blur(26px);
    --ap-blur-lg: saturate(195%) blur(36px);

    /* Radii */
    --ap-r-xs: 8px;
    --ap-r-sm: 12px;
    --ap-r-md: 16px;
    --ap-r-lg: 22px;
    --ap-r-xl: 28px;
    --ap-r-full: 999px;

    /* Specular Highlights & Elevation */
    --ap-inner-hi: inset 0 0.5px 0 rgba(255, 255, 255, 0.18);
    --ap-inner-glow: inset 0 0.5px 0 rgba(255, 255, 255, 0.26), inset 0 0 12px rgba(255, 255, 255, 0.04);
    --ap-sh-sm: 0 2px 8px rgba(0, 0, 0, 0.20), 0 1px 2px rgba(0, 0, 0, 0.16);
    --ap-sh-md: 0 10px 30px rgba(0, 0, 0, 0.34), 0 2px 6px rgba(0, 0, 0, 0.22);
    --ap-sh-lg: 0 20px 55px rgba(0, 0, 0, 0.50), 0 4px 14px rgba(0, 0, 0, 0.28);

    /* Motion */
    --ap-ease: cubic-bezier(0.22, 1, 0.36, 1);
    --ap-spring: cubic-bezier(0.34, 1.45, 0.64, 1);
    --ap-dur: 0.24s;
    --ap-dur-press: 0.09s;
    --ap-dur-panel: 0.32s;
}

/* -----------------------------------------------------------------------------
   1 · SF PRO TYPOGRAPHY & ICON FONT PROTECTION
   -------------------------------------------------------------------------- */

html body,
html body input,
html body textarea,
html body select,
html body button:not([class*="fa-"]),
html body .menu_button:not([class*="fa-"]),
html body .text_pole {
    font-family: var(--ap-font) !important;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

/* Strictly preserve Font Awesome on icon buttons & pseudo-elements */
html body .fa,
html body .fas,
html body .far,
html body .fa-solid,
html body .fa-regular,
html body .fa-classic,
html body .menu_button.fa-solid,
html body .menu_button.fa-regular,
html body .menu_button.fas,
html body .right_menu_button.fa-solid,
html body .drawer-icon.fa-solid,
html body .mes_button.fa-solid,
html body .mes_button.fa-regular {
    font-family: "Font Awesome 6 Free", "Font Awesome 5 Free", FontAwesome !important;
}

html body .fab,
html body .fa-brands,
html body .menu_button.fa-brands {
    font-family: "Font Awesome 6 Brands", "Font Awesome 5 Brands" !important;
}

html body code,
html body pre,
html body .mes_text code,
html body .monospace {
    font-family: var(--ap-mono) !important;
}

/* Crisp Apple rendering — no muddy text-shadows */
html body * {
    text-shadow: none !important;
}

html body {
    letter-spacing: -0.011em;
    color: var(--ap-label);
}

html body #chat .mes .mes_text {
    font-size: 15.5px !important;
    line-height: 1.68 !important;
    letter-spacing: -0.005em !important;
    color: var(--ap-label) !important;
}

html body #chat .mes .mes_text p {
    margin-top: 0 !important;
    margin-bottom: 0.65em !important;
}

html body #chat .mes .mes_text p:last-child {
    margin-bottom: 0 !important;
}

html body #chat .mes[is_user="false"] .mes_text q {
    color: #7cc0ff !important;
}

html body h1,
html body h2,
html body h3,
html body h4,
html body h5 {
    letter-spacing: -0.02em !important;
    font-weight: 600 !important;
    color: var(--ap-label);
}

/* -----------------------------------------------------------------------------
   2 · ULTRA-SLIM OVERLAY SCROLLBARS & RESIZER CLEANUP
   -------------------------------------------------------------------------- */

html body ::-webkit-scrollbar {
    width: 5px !important;
    height: 5px !important;
    background: transparent !important;
}

html body ::-webkit-scrollbar-track,
html body ::-webkit-scrollbar-track:hover,
html body ::-webkit-scrollbar-track:active {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

html body ::-webkit-scrollbar-thumb,
html body ::-webkit-scrollbar-thumb:vertical,
html body ::-webkit-scrollbar-thumb:horizontal {
    background: rgba(255, 255, 255, 0.16) !important;
    border: none !important;
    border-radius: var(--ap-r-full) !important;
    box-shadow: none !important;
}

html body ::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.34) !important;
}

html body ::-webkit-scrollbar-thumb:active {
    background: rgba(255, 255, 255, 0.48) !important;
}

html body ::-webkit-scrollbar-corner,
html body ::-webkit-resizer {
    background: transparent !important;
    display: none !important;
}

/* -----------------------------------------------------------------------------
   3 · FLOATING TOP BAR (Dynamic Island / macOS Frosted Pill)
   -------------------------------------------------------------------------- */

html body #top-bar {
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: none !important;
    box-shadow: none !important;
}

/* Dynamic Island: the holder shrink-wraps its 9 icons and self-centers, drawing
   the frosted capsule through ::before. Child drawers are position:fixed so they
   always measure against the viewport — never against the pill — which keeps the
   centered dropdowns perfectly aligned at any window width. */
html body #top-settings-holder {
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    width: fit-content !important;
    max-width: calc(100vw - 12px) !important;
    height: var(--topBarBlockSize) !important;
    margin: 0 auto !important;
    padding: 0 9px !important;
    gap: 1px !important;
    justify-content: center !important;
    align-items: center !important;
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: none !important;
    box-shadow: none !important;
    z-index: 3005;
}

html body #top-settings-holder::before {
    content: "";
    position: absolute;
    top: 3px;
    bottom: 3px;
    left: 0;
    right: 0;
    width: auto;
    transform: none;
    background: var(--ap-glass-pill);
    backdrop-filter: var(--ap-blur-lg);
    -webkit-backdrop-filter: var(--ap-blur-lg);
    border: 1px solid var(--ap-hairline);
    border-radius: var(--ap-r-full);
    box-shadow: var(--ap-inner-hi), var(--ap-sh-md);
    pointer-events: none;
    z-index: 0;
}

/* Reset .drawer wrapper inside top bar so all 9 icons cluster tightly inside
   the centered 388px Dynamic Island frosted pill */
html body:not(#_):not(#__) #top-settings-holder > .drawer,
html body:not(#_):not(#__) .drawer {
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 0 2px !important;
    margin: 0 !important;
    flex: 0 0 auto !important;
    width: auto !important;
    z-index: 1;
}

/* Top bar icon capsules */
html body #top-settings-holder .drawer-icon,
html body .drawer-icon {
    width: 34px !important;
    height: 29px !important;
    min-width: 34px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 16px !important;
    line-height: 1 !important;
    color: var(--ap-label-2) !important;
    border-radius: var(--ap-r-full) !important;
    border: 1px solid transparent !important;
    background: transparent !important;
    padding: 0 !important;
    opacity: 0.85 !important;
    transition: background-color var(--ap-dur) var(--ap-ease),
        border-color var(--ap-dur) var(--ap-ease),
        box-shadow var(--ap-dur) var(--ap-ease),
        color var(--ap-dur) var(--ap-ease),
        opacity var(--ap-dur) var(--ap-ease) !important;
}

html body #top-settings-holder .drawer-icon.closedIcon,
html body .drawer-icon.closedIcon {
    opacity: 0.55 !important;
}

html body #top-settings-holder .drawer-icon:hover,
html body #top-settings-holder .drawer-icon.closedIcon:hover,
html body .drawer-icon:hover {
    color: #fff !important;
    opacity: 1 !important;
    background: rgba(255, 255, 255, 0.13) !important;
    border-color: rgba(255, 255, 255, 0.16) !important;
    box-shadow: var(--ap-inner-hi) !important;
}

html body #top-settings-holder .drawer-icon.openIcon,
html body #top-settings-holder .drawer-icon.active,
html body .drawer-icon.openIcon,
html body .drawer-icon.active {
    color: #fff !important;
    background: linear-gradient(180deg, #2e95ff 0%, #0a84ff 100%) !important;
    border-color: rgba(255, 255, 255, 0.25) !important;
    box-shadow: inset 0 0.5px 0 rgba(255, 255, 255, 0.35),
        0 4px 14px rgba(10, 132, 255, 0.45) !important;
}

html body #top-settings-holder .drawer-icon:active,
html body .drawer-icon:active {
    transform: scale(0.92) !important;
}

/* -----------------------------------------------------------------------------
   4 · FLOATING GLASS SHEETS / SIDE PANELS / TOP DRAWERS
   -------------------------------------------------------------------------- */

html body:not(#_):not(#__) .drawer-content,
html body:not(#_):not(#__) #left-nav-panel,
html body:not(#_):not(#__) #right-nav-panel,
html body:not(#_):not(#__) #character_popup,
html body:not(#_):not(#__) #logprobsViewer,
html body:not(#_):not(#__) #floatingPrompt,
html body:not(#_):not(#__) #cfgConfig {
    background: var(--ap-glass-sheet) !important;
    backdrop-filter: var(--ap-blur-lg) !important;
    -webkit-backdrop-filter: var(--ap-blur-lg) !important;
    border: 1px solid var(--ap-hairline) !important;
    border-radius: var(--ap-r-lg) !important;
    box-shadow: var(--ap-inner-hi), var(--ap-sh-lg) !important;
    /* Anchor every dropdown against the VIEWPORT, not the shrink-wrapped pill */
    position: fixed !important;
}

/* Center-anchored dropdown drawers (User Settings, World Info, Formatting, API,
   Extensions, Personas…) get Apple System-Settings width, comfortable padding
   and a consistent gap below the Dynamic Island. */
html body:not(#_):not(#__) .drawer-content:not(.fillLeft):not(.fillRight) {
    top: calc(var(--topBarBlockSize) + 9px) !important;
    left: 0 !important;
    right: 0 !important;
    width: min(1000px, calc(100vw - 24px)) !important;
    min-width: 0 !important;
    max-height: calc(100dvh - var(--topBarBlockSize) - 22px) !important;
    padding: 16px 20px !important;
    margin: 0 auto !important;
}

/* Left / right rail panels: hug the viewport edges, never the pill */
html body:not(#_):not(#__) #left-nav-panel,
html body:not(#_):not(#__) #right-nav-panel,
html body:not(#_):not(#__) .fillLeft,
html body:not(#_):not(#__) .fillRight {
    top: calc(var(--topBarBlockSize) + 8px) !important;
    height: calc(100dvh - var(--topBarBlockSize) - 16px) !important;
    max-height: calc(100dvh - var(--topBarBlockSize) - 16px) !important;
    padding: 12px 12px 14px !important;
    border-radius: var(--ap-r-lg) !important;
}

@media screen and (min-width: 1001px) {
    html body:not(#_):not(#__) #right-nav-panel {
        right: 8px !important;
        left: auto !important;
        width: max(300px, calc((100dvw - var(--sheldWidth)) / 2 - 14px)) !important;
        margin: 0 !important;
    }
    html body:not(#_):not(#__) #left-nav-panel {
        left: 8px !important;
        right: auto !important;
        width: max(300px, calc((100dvw - var(--sheldWidth)) / 2 - 14px)) !important;
        margin: 0 !important;
    }
}

/* Eliminate ugly dark gradient bars on section headers (UI 主题, 角色处理, 杂项, 自定义 CSS, etc.) */
html body:not(#_):not(#__) .title_restorable,
html body:not(#_):not(#__) #user-settings-block h4,
html body:not(#_):not(#__) #left-nav-panel .title_restorable,
html body:not(#_):not(#__) .drawer-content h4,
html body:not(#_):not(#__) #rm_button_selected_ch {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    border: none !important;
    border-bottom: 1px solid var(--ap-hairline-subtle) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    padding: 6px 2px 8px !important;
    margin: 10px 0 10px !important;
    font-weight: 600 !important;
    color: var(--ap-label) !important;
}

/* Section-header icon buttons (Expand editor "maximize", Help "?", palette, eye…)
   must read as lightweight Apple GHOST buttons, not solid dark squares. */
html body:not(#_):not(#__) .title_restorable .menu_button,
html body:not(#_):not(#__) .title_restorable .right_menu_button,
html body:not(#_):not(#__) .editor_maximize,
html body:not(#_):not(#__) #description_div .right_menu_button,
html body:not(#_):not(#__) #first_message_div .right_menu_button,
html body:not(#_):not(#__) #creators_notes_div .menu_button,
html body:not(#_):not(#__) .notes-link .note-link-span {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    color: var(--ap-label-2) !important;
    opacity: 0.9 !important;
    width: 26px !important;
    height: 26px !important;
    min-width: 26px !important;
    min-height: 26px !important;
    padding: 0 !important;
    border-radius: var(--ap-r-full) !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 14px !important;
    transition: background-color var(--ap-dur) var(--ap-ease),
        color var(--ap-dur) var(--ap-ease) !important;
}

html body:not(#_):not(#__) .title_restorable .menu_button:hover,
html body:not(#_):not(#__) .title_restorable .right_menu_button:hover,
html body:not(#_):not(#__) .editor_maximize:hover,
html body:not(#_):not(#__) #creators_notes_div .menu_button:hover {
    background: var(--ap-fill-2) !important;
    color: #fff !important;
    opacity: 1 !important;
}

/* The "?" documentation link keeps Apple's accent tint */
html body:not(#_):not(#__) .notes-link .note-link-span {
    color: var(--ap-blue-hover) !important;
}

html body:not(#_):not(#__) .notes-link:hover .note-link-span {
    color: #fff !important;
    background: var(--ap-fill-2) !important;
}

/* "Expanded editor" (maximize toggle) active state gets a subtle accent fill */
html body:not(#_):not(#__) .editor_maximize.active {
    background: rgba(10, 132, 255, 0.28) !important;
    color: #fff !important;
}

/* Spacious 3-column layout inside User Settings */
html body:not(#_):not(#__) #user-settings-block-content {
    gap: 20px !important;
}

/* -----------------------------------------------------------------------------
   5 · CAPSULE BUTTONS — Frosted Glass + Hover Glow + Spring Scale (0.96)
       NOTE: backdrop-filter is deliberately NOT used on small buttons. Blurring
       700+ tiny elements forces a full-page re-raster on every hover and makes
       the UI flicker. Only large surfaces (panels, popovers, composer) blur.
   -------------------------------------------------------------------------- */

html body .menu_button,
html body .menu_button_icon,
html body .right_menu_button,
html body .qr--button,
html body #qr-bar .menu_button,
html body .xiaobaix-task-button,
html body .immersive-nav-btn,
html body .TH-reference-button,
html body .TH-Button--container {
    color: var(--ap-label) !important;
    background: var(--ap-fill-2) !important;
    border: 1px solid var(--ap-hairline) !important;
    border-radius: var(--ap-r-full) !important;
    box-shadow: var(--ap-inner-hi) !important;
    filter: none !important;
    font-weight: 500 !important;
    letter-spacing: -0.01em;
    padding: 5px 12px;
    cursor: pointer;
    transition: background-color var(--ap-dur) var(--ap-ease),
        border-color var(--ap-dur) var(--ap-ease),
        box-shadow var(--ap-dur) var(--ap-ease),
        color var(--ap-dur) var(--ap-ease),
        transform var(--ap-dur) var(--ap-spring) !important;
}

/* Compact icon buttons in character / panel grids stay neat capsules */
html body .buttons_block .menu_button,
html body .right_menu_button,
html body .menu_button.fa-solid:not(.menu_button_icon),
html body .menu_button.fa-regular:not(.menu_button_icon) {
    padding: 5px 8px !important;
    min-width: 30px !important;
    min-height: 30px !important;
    align-items: center !important;
    justify-content: center !important;
    border-radius: var(--ap-r-full) !important;
}

html body .menu_button:hover:not(.disabled):not([disabled]),
html body .menu_button_icon:hover:not(.disabled):not([disabled]),
html body .right_menu_button:hover,
html body .qr--button:hover,
html body #qr-bar .menu_button:hover,
html body .xiaobaix-task-button:hover,
html body .immersive-nav-btn:hover:not(:disabled),
html body .TH-reference-button:hover,
html body .TH-Button--container:hover {
    background: var(--ap-fill-1) !important;
    border-color: var(--ap-hairline-strong) !important;
    box-shadow: var(--ap-inner-glow), 0 3px 10px rgba(0, 0, 0, 0.22) !important;
    color: #fff !important;
}

html body .menu_button:active:not(.disabled):not([disabled]),
html body .menu_button_icon:active:not(.disabled):not([disabled]),
html body .right_menu_button:active,
html body .qr--button:active,
html body #qr-bar .menu_button:active,
html body .xiaobaix-task-button:active,
html body .immersive-nav-btn:active:not(:disabled),
html body .TH-reference-button:active,
html body .TH-Button--container:active {
    transform: scale(0.96) !important;
    background: rgba(160, 160, 175, 0.30) !important;
}

/* Active / toggled state */
html body .menu_button.toggleable.toggled,
html body .menu_button.active,
html body .menu_button:not(.disabled).active {
    background: linear-gradient(180deg, #2e95ff 0%, #0a84ff 100%) !important;
    border-color: rgba(255, 255, 255, 0.26) !important;
    color: #fff !important;
    box-shadow: inset 0 0.5px 0 rgba(255, 255, 255, 0.32),
        0 4px 14px rgba(10, 132, 255, 0.42) !important;
}

html body .menu_button[disabled],
html body .menu_button.disabled {
    opacity: 0.38 !important;
    pointer-events: none;
}

/* Primary / confirm modal buttons (beats .popup-controls .menu_button in Moonlit) */
html body:not(#_):not(#__) .popup-controls .menu_button,
html body:not(#_):not(#__) .menu_button.popup-button-ok,
html body:not(#_):not(#__) #dialogue_popup_ok,
html body:not(#_):not(#__) .menu_button.menu_button_default,
html body:not(#_):not(#__) #dialogue_popup_cancel {
    border-radius: var(--ap-r-full) !important;
    padding: 7px 22px !important;
    font-weight: 600 !important;
    border: 1px solid var(--ap-hairline) !important;
    background: var(--ap-fill-2) !important;
    box-shadow: var(--ap-inner-hi), var(--ap-sh-sm) !important;
}

html body:not(#_):not(#__) .menu_button.popup-button-ok,
html body:not(#_):not(#__) #dialogue_popup_ok {
    background: linear-gradient(180deg, #2e95ff 0%, #0a84ff 100%) !important;
    border-color: rgba(255, 255, 255, 0.25) !important;
    color: #fff !important;
    box-shadow: inset 0 0.5px 0 rgba(255, 255, 255, 0.32),
        0 4px 14px rgba(10, 132, 255, 0.40) !important;
}

html body:not(#_):not(#__) .menu_button.popup-button-ok:hover,
html body:not(#_):not(#__) #dialogue_popup_ok:hover {
    background: linear-gradient(180deg, #4da6ff 0%, #1c8fff 100%) !important;
}

/* Destructive / danger buttons */
html body .menu_button.redWarningBG,
html body #delete_button {
    background: rgba(255, 69, 58, 0.22) !important;
    border-color: rgba(255, 69, 58, 0.42) !important;
    color: #ff6961 !important;
}

html body .menu_button.redWarningBG:hover,
html body #delete_button:hover {
    background: rgba(255, 69, 58, 0.36) !important;
    color: #fff !important;
}

/* -----------------------------------------------------------------------------
   6 · FROSTED INPUT FIELDS & TEXTAREAS
       (Excludes Select2 inline search input so World Info never double-borders!)
   -------------------------------------------------------------------------- */

html body:not(#_):not(#__) .text_pole:not(.neo-range-input),
html body:not(#_):not(#__) input[type="text"]:not([id^="xiaobaix_"]):not(.select2-search__field),
html body:not(#_):not(#__) input[type="search"]:not(.select2-search__field),
html body:not(#_):not(#__) input[type="number"]:not([id^="xiaobaix_"]):not(.neo-range-input),
html body:not(#_):not(#__) input[type="password"],
html body:not(#_):not(#__) textarea:not(#send_textarea):not([id^="xiaobaix_"]):not(.select2-search__field),
html body:not(#_):not(#__) select.text_pole,
html body:not(#_):not(#__) select:not([id^="xiaobaix_"]) {
    background: rgba(118, 118, 128, 0.18) !important;
    color: var(--ap-label) !important;
    border: 1px solid var(--ap-hairline) !important;
    border-radius: var(--ap-r-sm) !important;
    box-shadow: var(--ap-inner-hi) !important;
    padding: 6px 11px !important;
