/* -----------------------------------------------------------------------------
   15 · AUDIT ROUND 2 — layout collisions, hidden-state respect, compact rails
   -------------------------------------------------------------------------- */

/* 15a · Chat column never slides under a pinned rail (1001–1366px used to hide
   the Send button behind the 300px Character panel). The column keeps its
   configured width when there is room, and is clamped between the rails. */
@media screen and (min-width: 1001px) {
    html body:has(#right-nav-panel.pinnedOpen.openDrawer) {
        --ap-rail-r: calc(max(300px, (100vw - var(--sheldWidth)) / 2 - 14px) + 8px);
    }
    html body:has(#left-nav-panel.pinnedOpen.openDrawer) {
        --ap-rail-l: calc(max(300px, (100vw - var(--sheldWidth)) / 2 - 14px) + 8px);
    }
    html body:not(#_):not(#__) #sheld {
        --ap-sw: min(var(--sheldWidth), calc(100vw - var(--ap-rail-l, 0px) - var(--ap-rail-r, 0px) - 12px));
        width: var(--ap-sw) !important;
        right: auto !important;
        margin-left: 0 !important;
        margin-right: 0 !important;
        left: clamp(calc(var(--ap-rail-l, 0px) + 6px),
                    calc((100vw - var(--ap-sw)) / 2),
                    calc(100vw - var(--ap-rail-r, 0px) - var(--ap-sw) - 6px)) !important;
    }
}

/* 15b · Top-bar sheets open ABOVE pinned rails (rails had z-index 3000 and
   covered the right third of Extensions / Persona / User Settings). */
/* Each top-bar .drawer is a flex item with z-index:1, i.e. its own stacking
   context — so the sheet's own z-index can't escape it. Lift the WRAPPER of
   the open sheet instead (rightNavHolder comes later in DOM and won otherwise). */
html body:not(#_):not(#__) #top-settings-holder > .drawer:has(> .drawer-content.openDrawer:not(.fillLeft):not(.fillRight)) {
    z-index: 5 !important;
}

